/* AMC expiry reminders share the service reminder workspace. */
let reminderView='service',amcReminderFilter='due',amcReminderWindow='30';
function amcExpiryDays(c,date=today()){if(!c.amcType||!validAmcDate(c.amcExpiry))return null;return Math.round((Date.parse(c.amcExpiry+'T00:00:00Z')-Date.parse(date+'T00:00:00Z'))/86400000)}
function amcExpiryMessage(c){let days=amcExpiryDays(c);return `${db.settings.name}\nAMC Expiry Reminder\nDear ${c.name},\nYour ${c.amcType} ${days<0?'expired on':'expires on'} ${c.amcExpiry}.${c.amcRef?'\nAgreement: '+c.amcRef:''}\nPlease contact us to discuss renewal.${db.settings.phone?'\nContact: '+db.settings.phone:''}\nThank you.`}
function amcReminderLastLog(c){return (db.amcReminderLogs||[]).filter(l=>l.customer===c.id&&l.expiryDate===c.amcExpiry&&l.amcType===c.amcType).sort((a,b)=>b.at.localeCompare(a.at))[0]}
function logAmcReminder(id,note){let c=find('customers',id);if(!c||amcExpiryDays(c)===null)throw Error('Set a valid AMC type and expiry date first.');let before=structuredClone(db);db.amcReminderLogs=db.amcReminderLogs||[];db.amcReminderLogs.push({id:'AMC-R-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),customer:id,amcType:c.amcType,expiryDate:c.amcExpiry,at:new Date().toISOString(),note:String(note||'').slice(0,500),status:'User confirmed sent'});audit('AMC Reminder',c.id+' marked sent by user for '+c.amcExpiry);if(save('AMC reminder recorded as sent by you')===false){db=before;return false}return true}
function amcReminderRows(){return db.customers.filter(c=>c.amcType).filter(matches).filter(c=>{let days=amcExpiryDays(c);return amcReminderFilter==='all'||amcReminderFilter==='due'&&days!==null&&days<=0||amcReminderFilter==='expired'&&days!==null&&days<0||amcReminderFilter==='today'&&days===0||amcReminderFilter==='upcoming'&&days!==null&&days>0&&days<=Number(amcReminderWindow)||amcReminderFilter==='incomplete'&&days===null}).sort((a,b)=>(a.amcExpiry||'9999').localeCompare(b.amcExpiry||'9999'))}
function amcRemindersPage(){let all=db.customers.filter(c=>c.amcType);return summary([['EXPIRED AMC',all.filter(c=>{let d=amcExpiryDays(c);return d!==null&&d<0}).length],['EXPIRES TODAY',all.filter(c=>amcExpiryDays(c)===0).length],['EXPIRING WITHIN 30 DAYS',all.filter(c=>{let d=amcExpiryDays(c);return d!==null&&d>0&&d<=30}).length],['TOTAL AMC CUSTOMERS',all.length]])+`<div class="notice">AMC reminders use the expiry date in Customer Master. Review the WhatsApp message and send it yourself, then record it as sent. Updating the expiry date starts a new renewal reminder cycle.</div>`+toolbar('',`<select id="amcReminderFilter" aria-label="AMC expiry reminder filter">${opts([{value:'due',label:'Expired & Expires Today'},{value:'expired',label:'Expired'},{value:'today',label:'Expires Today'},{value:'upcoming',label:'Expiring Soon'},{value:'all',label:'All AMC Customers'},{value:'incomplete',label:'Missing Expiry Date'}],amcReminderFilter)}</select><select id="amcReminderWindow" aria-label="AMC reminder window">${opts([{value:'7',label:'Next 7 Days'},{value:'30',label:'Next 30 Days'},{value:'90',label:'Next 90 Days'}],amcReminderWindow)}</select><button type="button" class="btn" data-page="customers">Manage Customer AMC</button>`)+table(['Customer ID','Customer Name','Mobile','Vehicles','AMC Type','Valid From','Expiry Date','AMC Status','Days to Expiry','Agreement Reference','Last Reminder Sent','Actions'],amcReminderRows().map(c=>{let days=amcExpiryDays(c),log=amcReminderLastLog(c);return [esc(c.id),esc(c.name),esc(c.mobile||'—'),esc(db.bikes.filter(b=>b.customer===c.id).map(b=>b.number).join(', ')||'—'),esc(c.amcType),esc(c.amcStart||'—'),esc(c.amcExpiry||'—'),badge(customerAmcStatus(c)),days===null?'Missing expiry':days<0?Math.abs(days)+' days expired':days===0?'Expires today':days+' days remaining',esc(c.amcRef||'—'),log?esc(uiDateTime(log.at))+' (manual)':'—',`<div class="rowactions"><button type="button" class="btn small extraAction green" data-amc-whatsapp="${esc(c.id)}" title="WhatsApp AMC Expiry Reminder" ${days===null?'disabled':''}>${whatsappIcon()}</button><button type="button" class="btn small editButton" data-edit="customers|${esc(c.id)}" title="Edit AMC Details">${icon('edit')}</button><button type="button" class="btn small extraAction blue" data-amc-reminder-sent="${esc(c.id)}" title="Record AMC Reminder Sent" ${days===null?'disabled':''}>${icon('check')}</button></div>`]}))}
const remindersBeforeAmc=serviceRemindersPage;
serviceRemindersPage=function(){let serviceCount=db.bikes.filter(b=>{let d=serviceDueDays(b);return d!==null&&d<=0}).length,amcCount=db.customers.filter(c=>{let d=amcExpiryDays(c);return d!==null&&d<=0}).length;return `<div class="tabs reminderTabs"><button type="button" class="tab ${reminderView==='service'?'active':''}" data-reminder-view="service">Vehicle Service (${serviceCount} due)</button><button type="button" class="tab ${reminderView==='amc'?'active':''}" data-reminder-view="amc">AMC Expiry (${amcCount} due)</button></div>`+(reminderView==='amc'?amcRemindersPage():remindersBeforeAmc())};
/* The original vehicle-only bindings are skipped while the AMC tab is active. */
const renderBeforeAmcReminders=render;
render=function(){renderBeforeAmcReminders();if(page!=='service-reminders')return;for(let b of $$('[data-reminder-view]'))b.onclick=()=>{reminderView=b.dataset.reminderView;search='';render()};if(reminderView!=='amc')return;$('#amcReminderFilter').onchange=e=>{amcReminderFilter=e.target.value;render()};$('#amcReminderWindow').onchange=e=>{amcReminderWindow=e.target.value;render()};for(let b of $$('[data-amc-whatsapp]'))b.onclick=()=>{let c=find('customers',b.dataset.amcWhatsapp);messagePreview(c.mobile,amcExpiryMessage(c))};for(let b of $$('[data-amc-reminder-sent]'))b.onclick=()=>{let id=b.dataset.amcReminderSent,c=find('customers',id);openModal('Record AMC Reminder Sent',`<form id="amcReminderSentForm"><div class="formbody"><p>Confirm you sent the AMC renewal reminder to <strong>${esc(c.name)}</strong> for expiry ${esc(c.amcExpiry)}. Opening WhatsApp alone does not confirm sending.</p><label class="field"><span>Note / Contact Method</span><input name="note" maxlength="500"></label></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button type="submit" class="btn">Confirm I Sent the Reminder</button></div></form>`);$('#amcReminderSentForm').onsubmit=e=>{e.preventDefault();try{if(logAmcReminder(id,new FormData(e.target).get('note'))){closeModal();render()}}catch(err){toast(err.message)}}}};
titles['service-reminders']='Service & AMC Reminders';let reminderMenu=groups.find(g=>g[0]==='OPERATIONS')[1].find(m=>m[0]==='service-reminders');if(reminderMenu)reminderMenu[1]='Service & AMC Reminders';
render();
